async function settings(q){const tab=q.get('tab')||'health',health=await api('health');return title('Settings & Data Health','Local persistence, evidence freshness and measured run activity.')+tabs('settings',[['health','Sources'],['trends','Weekly trends'],['runs','Runs'],['history','History'],['backups','Backups']],tab)+(tab==='trends'?await trendsView(q):tab==='history'?await historyView(q):tab==='backups'?`<section class="panel"><h2>Backups & migration</h2><p>Database backups retain 30 days. Restoring first saves the current database and invalidates prepared approvals.</p><div class="actions">${btn('Create backup','backup')}<a class="button" href="/api/export">Export data</a></div><label>Import legacy browser progress export<input id="migration" type="file" accept="application/json"></label>${health.backups.map(n=>`<p><code>${esc(n)}</code> ${btn('Restore','restore',n)}</p>`).join('')}</section>`:tab==='runs'?`<section class="panel"><h2>Last 30 runs</h2><p>Unknown metrics stay unknown. Shared account quota is not a per-run bill.</p>${health.runs.map(r=>`<details><summary>${esc(fmt(r.startedAt))} · ${esc(r.model)} · ${esc(r.status)}</summary><pre>${esc(JSON.stringify(r,null,2))}</pre></details>`).join('')||'<p>No measured runs yet.</p>'}</section>`:D.sources.map(s=>`<section class="panel"><h3>${esc(s.name)} <span class="tag ${s.status!=='ok'?'warn':''}">${esc(s.status)}</span></h3><p>${esc(s.note)}</p><small>Last success: ${esc(fmt(s.lastSuccess))}</small></section>`).join('')+`<section class="panel"><h2>Weekly review</h2><p>${esc(D.weeklyReview)}</p><p>Latest user-reported career statuses: ${esc(JSON.stringify(R.weekly(careerHistory(),new Date().toISOString())))}</p>${Object.entries(S.actual||{}).map(([id,n])=>`<p>${esc(D.assignments.find(a=>a.id===id)?.title||id)}: ${n} actual minutes / ${D.assignments.find(a=>a.id===id)?.estimateMinutes??'unknown'} estimated</p>`).join('')}<small>Effort is cumulative, not necessarily this week.</small><a href="/settings?tab=trends">Dated weekly evidence trends →</a></section>`+calibration());}

const dirty=new Set();
const localInput=x=>{const parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:D.timezone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(x)).map(p=>[p.type,p.value]));return parts.year+'-'+parts.month+'-'+parts.day+'T'+parts.hour+':'+parts.minute;};
// Receipts per exact version. States come only from local receipts recorded by the operator tool; the page never executes.
const receiptLabel={prepared:'Prepared · not authorized or executed',pending:'Pending · write started or outcome not yet read back',unverified:'Unverified · outcome uncertain; reconcile before anything else',executed:'Executed · read back and verified',not_created:'Not created · verified absent',invalidated:'Invalidated · changed after preparation'};
const refLabel=x=>x.kind+' '+x.id+(x.version?' v'+x.version:'');
function receiptRow(r,p){const h=D.actionHistory.find(h=>h.id===p.id&&h.fingerprint===P.fingerprint(p)),st=h?h.status:r.status==='invalidated'?'invalidated':'prepared',a=h?.humanApproval;
 return `<li data-receipt="${esc(p.id)}" data-status="${esc(st)}"><strong>${esc(p.title)}</strong> <span class="tag ${st==='executed'?'':'warn'}">${esc(receiptLabel[st]||st)}</span><small>${esc(calendarLabel(p))} · ${esc(fmt(p.start))} – ${esc(fmt(p.end))} · action ${esc(p.id)}</small>${(p.sourceRefs||[]).length?`<small>Source: ${esc(p.sourceRefs.map(refLabel).join(', '))}</small>`:''}${h?`<small>Recorded ${esc(fmtFull(h.recordedAt))}${h.reference&&h.reference!==r.reference?' under '+esc(h.reference):''}${h.verifiedAt?' · verified '+esc(fmtFull(h.verifiedAt)):''}${h.remoteRef?' · remote event '+esc(h.remoteRef):''}${h.idempotencyKey?' · key '+esc(h.idempotencyKey):''}</small>${a?`<small>Approval: ${esc(typeof a==='string'?a:'“'+a.text+'” ('+a.channel+', '+fmtFull(a.at)+')')}</small>`:''}${h.evidence?`<small class="receipt-evidence">Evidence: ${esc(h.evidence)}</small>`:''}${(h.attempts||[]).length?`<details><summary>Earlier states (${h.attempts.length})</summary><ul>${h.attempts.map(x=>`<li>${esc(x.status)} · ${esc(fmtFull(x.recordedAt))}${x.evidence?' · '+esc(x.evidence):''}</li>`).join('')}</ul></details>`:''}`:''}</li>`;}
function versionPanel(r){return `<section class="panel" data-version="${esc(r.reference)}"><h3>${r.reference} <span class="tag">${esc(r.status)}</span></h3><small>Prepared ${esc(fmt(r.at))}. This page only prepares versions; an authorized assistant writes after your explicit chat approval, re-checks your live calendar first and records each outcome here.</small><ul class="focus-list receipts">${r.value.map(p=>receiptRow(r,p)).join('')}</ul><details><summary>Immutable reviewed version</summary><pre>${esc(JSON.stringify(r.value.map(P.spec),null,2))}</pre></details></section>`;}
async function review(q){const tab=q.get('tab')||'current',versions=await api('approvals'),page=Math.max(1,Number(q.get('page'))||1);const base=title('Review Queue','Say “Approve Q-number” in chat after reviewing exact details. No copy/paste of a long prompt.')+tabs('review',[['current','Current'],['history','History']],tab);
 if(tab==='history')return base+D.proposals.filter(p=>S.dismissed?.[p.id]).map(p=>'<section class="panel"><h3>'+esc(p.title)+'</h3>'+btn('Restore proposal','undismiss',p.id)+'</section>').join('')+versions.slice((page-1)*20,page*20).map(versionPanel).join('')+paginate(versions.length,page,q,'review');
 return base+remaining().map(p=>{const errors=P.errors(p,D);return '<section class="panel"><label class="check"><input type="checkbox" data-progress="selected" data-id="'+esc(p.id)+'" '+(S.selected?.[p.id]?'checked':'')+' '+(errors.length?'disabled':'')+'><strong>'+esc(p.title)+'</strong></label><small>'+esc(calendarLabel(p))+' · '+esc(p.timezone)+'</small><p>'+esc(fmt(p.start))+' — '+esc(fmt(p.end))+'</p><p>'+esc(p.reason)+'</p><p class="error">'+esc(errors.join('; '))+'</p><details><summary>Exact destination and before / after</summary><p>Before: '+esc(JSON.stringify(p.before||'No event'))+'</p><pre>'+esc(JSON.stringify(P.spec(p),null,2))+'</pre></details><details><summary>Edit proposed block</summary><form class="proposalEdit" data-id="'+esc(p.id)+'"><label>Title<input name="title" required value="'+esc(p.title)+'"></label><label>Start · '+esc(D.timezone)+'<input name="start" type="datetime-local" required value="'+localInput(p.start)+'"></label><label>End · '+esc(D.timezone)+'<input name="end" type="datetime-local" required value="'+localInput(p.end)+'"></label><button>Save revised proposal</button></form></details>'+btn('Dismiss','dismiss',p.id)+'</section>';}).join('')+'<div class="actions">'+btn('Prepare selected confirmation','prepare')+'<small>Preparing creates an immutable version for you to approve in chat. It never writes to a calendar.</small></div>'+(()=>{const live=versions.filter(r=>['pending','partial','unverified'].includes(r.status));return live.length?'<h2>In progress</h2>'+live.map(versionPanel).join(''):'';})()+versions.filter(r=>r.status==='prepared').map(r=>'<section class="panel"><h3>'+r.reference+'</h3><p>Review '+r.value.length+' exact event(s), then say <strong>Approve '+r.reference+'</strong> in chat. Not yet authorized or executed.</p><details><summary>Exact version</summary><pre>'+esc(JSON.stringify(r.value.map(P.spec),null,2))+'</pre></details></section>').join('');
}
async function render(){const rev=++revision;try{const data=await api('snapshot');D=data.snapshot;S=data.progress;if(!D)throw Error('No database snapshot. Run the migration first.');C.configure(D.timezone);const path=location.pathname.slice(1)||'home',q=new URLSearchParams(location.search);$('#day').textContent=new Intl.DateTimeFormat('en-US',{timeZone:D.timezone,dateStyle:'full'}).format(new Date());document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.pathname==='/'+path));let html=path==='home'?home():path==='coursework'?coursework(q):path==='timetable'?timetable(q):path==='career'?career(q):path==='review'?await review(q):path==='settings'?await settings(q):path==='email'?email(q):title('Not found','');if(rev===revision)$('#page').innerHTML=html;$('#saved').textContent='Database connected · sources '+fmt(D.generatedAt);if(Date.now()-Date.parse(D.generatedAt)>26*3600000)$('#notice').innerHTML='<p class="banner">Source snapshot is stale. Check Data Health before acting.</p>';}catch(e){$('#notice').textContent=e.message;}}
async function save(kind,id,value){await api('progress',{kind,id,value});$('#saved').textContent='Saved to database';}
document.addEventListener('click',async e=>{const a=e.target.closest('a');if(a&&a.origin===location.origin&&!a.pathname.startsWith('/api/')){e.preventDefault();route(a.pathname+a.search);return;}const b=e.target.closest('button[data-action]');if(!b)return;try{const {action,id,value}=b.dataset;if(action==='archive')await save('archive',id,value==='true');if(action==='career')await save('career',id,{status:value,updatedAt:new Date().toISOString()});if(action==='backup')await api('backup',{});if(action==='restore'){if(!confirm('Restore this backup? A safety backup will be created first.'))return;await api('restore',{name:id});}if(action==='draft'){const x=[...D.career.roles,...D.career.candidates].find(x=>R.key(x)===id);$('#notice').innerHTML=`<label>Copy this short request into chat<textarea readonly>${esc('Draft for review: '+(x.name||x.title)+' — '+x.source+'. Recheck facts, use verified profile, identify gaps; do not send or apply.')}</textarea></label>`;return;}if(action==='help'){const x=D.assignments.find(x=>x.id===id);const saved=S.help?.[id]||{};$('#notice').innerHTML=`<section class="panel"><h3>${esc(x.title)}</h3><p>${esc(x.aiPolicy)}</p><form id="helpForm" data-id="${esc(id)}"><label>Mode<select name="mode"><option>outline</option><option>review</option><option>explain</option><option>draft</option></select></label><label>Actual notes / draft<textarea name="notes">${esc(saved.notes||'')}</textarea></label><label>Your argument<textarea name="argument">${esc(saved.argument||'')}</textarea></label><button>Prepare help request</button></form></section>`;return;}if(await actionExtra(action,id,value,b))return;await render();}catch(err){$('#notice').textContent=err.message;}});
async function actionExtra(action,id,value){if(action==='plan'){const r=await api('plan/generate',{date:value});await render();$('#notice').textContent=`Generated ${plural(r.blocks.length,'recommended block')} for ${value}${r.gaps.length?' (not planned: coverage gaps)':''}. Nothing was written to your calendar.`;return true;}if(action==='todoDone'||action==='todoReopen'){const r=await api('todos/complete',{id,done:action==='todoDone'});await render();$('#notice').textContent=(action==='todoDone'?'Todo completed.':'Todo reopened.')+(r.removedBlocks.length?` ${plural(r.removedBlocks.length,'unapproved planned block')} removed.`:'');return true;}if(action==='workloadMode'){const r=await api('workload-mode',{mode:value});await render();$('#notice').textContent='Focus mode: '+modeLabel[r.mode]+'. Advisory view only; nothing was scheduled, sent or approved.';return true;}if(action==='undismiss'){await save('dismissed',id,false);await render();return true;}if(action==='dismiss'){await save('dismissed',id,true);await render();return true;}if(action==='effortConfirm'||action==='effortClear'){opened.add(id);await api(action==='effortConfirm'?'effort/confirm':'effort/clear',{id});await render();$('#notice').textContent=action==='effortConfirm'?'Effort confirmed as a calibration sample. This is not a submission record.':'Effort confirmation cleared.';return true;}if(action==='prepare'){const selected=[...document.querySelectorAll('[data-progress="selected"]:checked')].filter(x=>!x.disabled).map(x=>x.dataset.id);if(selected.some(id=>dirty.has(id)))throw Error('Save revised proposals before preparing confirmation.');const r=await api('approvals/prepare',{ids:selected});await render();$('#notice').textContent='Prepared '+r.reference+'. Review the immutable version, then say “Approve '+r.reference+'” in chat.';return true;}return false;}
document.addEventListener('change',async e=>{try{const x=e.target;if(x.dataset.progress==='actual'){if(x.validity?.badInput)throw Error('Enter actual minutes as a number, or clear the field to remove it.');const r=await api('progress',{kind:'actual',id:x.dataset.id,value:x.value===''?null:Number(x.value)});opened.add(x.dataset.id);await render();$('#notice').textContent=r.invalidated?'Actual minutes changed: the earlier effort confirmation was removed. Reconfirm to include it.':'';$('#saved').textContent='Saved to database';}else if(x.dataset.progress)await save(x.dataset.progress,x.dataset.id,x.type==='checkbox'?x.checked:Number(x.value));if(x.id==='migration'){const data=JSON.parse(await x.files[0].text());await api('migrate-progress',data.localProgress||data);await render();$('#notice').textContent='Legacy progress imported. Existing database progress was preserved.';}}catch(err){$('#notice').textContent=err.message;}});
document.addEventListener('submit',async e=>{e.preventDefault();try{const form=e.target;if(form.dataset.filter){route('/'+form.dataset.filter+'?'+new URLSearchParams(new FormData(form)));return;}if(form.id==='helpForm'){const v=Object.fromEntries(new FormData(form)),x=D.assignments.find(x=>x.id===form.dataset.id);const text=P.helpRequest(x,v.mode,v.notes,v.argument);await save('help',x.id,v);$('#notice').innerHTML=`<label>Prepared help request<textarea readonly>${esc(text)}</textarea></label>`;}await submitExtra(form);}catch(err){$('#notice').textContent=err.message;}});
async function submitExtra(form){if(form.id==='todoForm'||form.classList.contains('todoEdit')||form.classList.contains('todoAdopt'))return todoSubmit(form);if(form.classList.contains('proposalEdit')){const v=Object.fromEntries(new FormData(form));for(const k of ['start','end']){const [day,time]=v[k].split('T');v[k]=C.zonedISO(day,time);}await api('proposals/edit',{id:form.dataset.id,changes:v});dirty.delete(form.dataset.id);await save('selected',form.dataset.id,false);await render();}}
document.addEventListener('input',async e=>{const form=e.target.closest('.proposalEdit');if(!form||dirty.has(form.dataset.id))return;dirty.add(form.dataset.id);try{await api('proposals/invalidate',{id:form.dataset.id});await save('selected',form.dataset.id,false);$('#notice').textContent='Edited proposal: earlier confirmation versions invalidated. Save before selecting again.';}catch(err){$('#notice').textContent=err.message;}});
document.addEventListener('toggle',e=>{const id=e.target.dataset?.open;if(id!==undefined)e.target.open?opened.add(id):opened.delete(id);},true);
window.addEventListener('popstate',render);
(async()=>{try{csrf=(await api('session')).csrf;await render();}catch(e){$('#notice').textContent=e.message;}})();
